std::size_t n = std::size(polygon);
if (n < 3) return CGAL::ON_UNBOUNDED_SIDE;

bool on_boundary = false;
for (std::size_t i = 0; i < n; ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % n];
    if (point == p1 || point == p2) return CGAL::ON_BOUNDARY;

    if (CGAL::collinear(p1, p2, point)) {
        if (CGAL::between_closed(p1, p2, point)) {
            return CGAL::ON_BOUNDARY;
        }
    }
}

int count = 0;
for (std::size_t i = 0; i < n; ++i) {
    const Point_2& p1 = polygon[i];
    const Point_2& p2 = polygon[(i + 1) % n];

    if (CGAL::collinear(p1, p2, point)) continue;

    if (CGAL::y(p1) > CGAL::y(p2)) {
        std::swap(p1, p2);
    }

    if (CGAL::y(p1) < CGAL::y(point) && CGAL::y(point) <= CGAL::y(p2)) {
        double x_intersect = (CGAL::y(p2) - CGAL::y(p1)) * (CGAL::x(point) - CGAL::x(p1)) /
                             (CGAL::y(p2) - CGAL::y(p1)) + CGAL::x(p1);
        if (CGAL::x(point) <= x_intersect) {
            ++count;
        }
    }
}

return (count % 2 == 1) ? CGAL::ON_BOUNDED_SIDE : CGAL::ON_UNBOUNDED_SIDE;
// END_CODE

